/* Месяцеслов «Православных» — 08.
   Каждый святой имеет краткое описание; lifeId — полное житие (src/lib/content/lives.ts). */

import type { SaintRec } from "./types";

export const M08: SaintRec[] = [
  { key: "08-01", name: "Прп. Макрины Каппадокийской, сестры свт. Василия Великого", kind: "saint", desc: "Прп. Макрина (IV век) – сестра святителей Василия Великого и Григория Нисского, родилась в Каппадокии. После смерти жениха она отказалась от замужества, посвятив жизнь воспитанию младших братьев и сестер, а затем вместе с матерью основала женский монастырь в своем имении в Понте." },
  { key: "08-01", name: "прп. Дия Константинопольского, игумена", kind: "saint", desc: "Прп. Дий (IV-V вв.) родился в благочестивой семье в Антиохии. С юности отличался крайним воздержанием: питался скудно, проводил ночи в молитвах, за что удостоился дара чудотворений." },
  { key: "08-01", name: "Обретение мощей прп. Серафима Саровского, чудотворца", kind: "saint", desc: "Прп. Серафим Саровский (в миру Прохор Мошнин, 1754-1833) — великий русский святой, родился в Курске в купеческой семье. В 7 лет упал с колокольни строящегося собора, но остался невредим.", lifeId: "serafim" },
  { key: "08-01", name: "Собор Курских святых", kind: "feast", desc: "Собор Курских святых – празднование Русской Православной Церкви в честь угодников Божиих, кто был родом из Курской губернии или служил в пределах Курской епархии." },
  { key: "08-01", name: "Блгв. кн. Романа (Олеговича) Рязанского", kind: "saint", desc: "Св. блгв. князь Роман Олегович Рязанский (1237–1270) происходил из благочестивого княжеского рода. Стал правителем Рязани в 1258 году после смерти отца." },
  { key: "08-01", name: "прп. Паисия Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Паисий был иноком Киево-Печерской лавры. Известна его духовная дружба с прп. Меркурием. Святые жили в единомыслии, разделяя одну келью, а после смерти были погребены в общем гробу." },
  { key: "08-01", name: "блж. Стефана Лазаревича Нового (Высокого)", kind: "saint", desc: "Блж. Стефан, сын св. князя Лазаря Сербского, прославился верой, милосердием и мудростью во времена турецкого ига, строя города и храмы, помогая нуждающимся." },
  { key: "08-01", name: "матери его блгв. кн. Милицы (во Святом Крещении Евфросинии) (1405), Сербских", kind: "saint", desc: "Св. Милица (†1405), вдова св. князя Лазаря, управляла Сербией до возмужания сына блж. Стефана. Приняв монашество (1393), продолжала править, помогала вдовам воинов, строила храмы." },
  { key: "08-02", name: "Прор. Илии", kind: "saint", desc: "Пророк Илия, величайший святой и первый девственник Ветхого Завета, родился за 900 лет до Р.Х. в Фесвии Галаадской. С юности подвизался в пустыне в посте и молитве.", lifeId: "iliya" },
  { key: "08-02", name: "Прп. Авраамия Галичского, Чухломского, игумена", kind: "saint", desc: "Прп. Авраамий Галичский, ученик прп. Сергия Радонежского, в 1350 году удалился в Галичские земли (совр. Костромская обл.), где на горе обрёл чудотворную икону Божией Матери." },
  { key: "08-02", name: "Обретение мощей прмч. Афанасия Брестского, игумена", kind: "saint", desc: "Прмч. Афанасий Брестский (1597-1648) – белорусский святой, ярый защитник Православия в эпоху насаждения Брестской унии. Приняв монашество, он стал игуменом Брестского Симеонова монастыря, где открыто обличал унию." },
  { key: "08-02", name: "Сщмч. Константина Словцова, пресвитера", kind: "saint", desc: "Сщмч. Константин Словцов (†1918) – выпускник Тобольской семинарии, рукоположенный в священники в 1912 году. Служил в селе Егоршинском Ирбитского уезда." },
  { key: "08-02", name: "Александра Архангельского", kind: "saint", desc: "Сщмч. Александр Архангельский (1874-1930) родился в семье псаломщика в Тамбовской губернии. Окончив Тамбовскую семинарию, принял священный сан и служил в сельских храмах Воронежской епархии, проявляя особую заботу о сиротах и нуждающихся." },
  { key: "08-02", name: "Георгия Никитина", kind: "saint", desc: "В начале 1930 года в Воронеже были арестованы священнослужители и миряне: священники Георгий Никитин, Александр Архангельский, иеромонахи Георгий (Пожаров), Кирилл (Вязников) и другие.", lifeId: "georgiy" },
  { key: "08-02", name: "Иоанна Стеблина-Каменского", kind: "saint", desc: "Сщмч. Иоанн Стеблин-Каменский (1887-1930) родился в Петербурге, в 1920 году стал диаконом, а в 1923-м – священником Троицкого храма на Стремянной. Неоднократно подвергался арестам: в 1921 году кратковременно заключён, в 1924-1927 годах отбывал срок в Соловецком лагере, после чего был сослан в Воронеж." },
  { key: "08-02", name: "Сергия Гортинского", kind: "saint", desc: "Сщмч. Сергий Гортинский (1889-1930) родился в семье священника в Рязани. После окончания училища, в 1916 году рукоположен в диакона, а в 1920-м ‒ в священника." },
  { key: "08-02", name: "Феодора Яковлева", kind: "saint", desc: "Сщмч. Феодор Яковлев (1897-1930) родился в крестьянской семье под Петербургом. Окончив Воронежское реальное училище, после революции служил в Красной армии и милиции." },
  { key: "08-02", name: "Тихона (Кречкова), архимандрита", kind: "saint", desc: "Прмч. Тихон (Кречков, 1862-1930) родился в крестьянской семье Воронежской губернии. Приняв монашество в Алексеевском монастыре, стал его казначеем. В 1924 году возведен в сан игумена, в 1927 ‒ архимандрита." },
  { key: "08-02", name: "Георгия (Пожарова), иеромонаха", kind: "saint", desc: "В начале 1930 года в Воронеже были арестованы священнослужители и миряне: архимандрит Тихон (Кречков), иеромонахи Георгий (Пожаров) и Кирилл (Вязников), священники Иоанн Стеблин-Каменский, Сергий Гортинский, Феодор Яковлев, Александр Архангельский, Георгий Никитин и миряне Евфимий Гребенщиков, Петр Вязников.", lifeId: "georgiy" },
  { key: "08-02", name: "Кирилла (Вязникова), иеромонаха", kind: "saint", desc: "В 1930 году в Воронеже были арестованы 10 верующих: архимандрит Тихон (Кречков), иеромонахи Кирилл (Вязников) и Георгий (Пожаров), священники Иоанн Стеблин-Каменский, Сергий Гортинский, Феодор Яковлев, Александр Архангельский, Георгий Никитин, а также миряне Евфимий Гребенщиков и Петр Вязников." },
  { key: "08-02", name: "сщмч. Алексия Знаменского, пресвитера", kind: "saint", desc: "Священномученик протоиерей Алексий Знаменский родился в 1882 году. 2 августа 1938 года, 56 лет от роду, он был расстрелян. Определением Священного Синода от 11 апреля 2006 года отец Алексий был прославлен в лике святых." },
  { key: "08-02", name: "прмч. Феодора Абросимова, послушника", kind: "saint", desc: "Прмч. Феодор Абросимов родился в поморской семье в селе Чаваньга. В 1913 году поступил в Трифоно-Печенгский монастырь, но был мобилизован на Первую мировую войну." },
  { key: "08-03", name: "Прор. Иезекииля", kind: "saint", desc: "Пророк Иезекииль (VI в. до Р.Х.), происходивший из священнического рода, был уведён в вавилонский плен в 25 лет. На 30-м году жизни у реки Ховар ему явилось видение Божественной славы: огненная колесница с четырьмя таинственными животными (прообраз евангелистов) и престол с \"подобием Человека\" (прообраз Христа)." },
  { key: "08-03", name: "Онуфрия Молчаливого", kind: "saint", desc: "Прп. Онуфрий Молчаливый (XII век), был подвижником Киево-Печерской лавры в Ближних Антониевых пещерах. Преподобный Онуфрий Молчаливый, Печерский, подвизался в Ближних Антониевых пещерах в XII веке." },
  { key: "08-03", name: "Онисима затворника, Печерских, в Ближних пещерах", kind: "saint", desc: "Прп. Онисим Печерский (XII-XIII вв.) ‒ затворник Киево-Печерской лавры, подвизался в Ближних пещерах, где и почивают его мощи. Преподобный Онисим Печерский (XII–XIII), подвизаясь в Киево-Печерской Лавре, затворился в Ближних пещерах (преподобного Антония)." },
  { key: "08-03", name: "мч. Виктора Марсельского", kind: "saint", desc: "Мч. Виктор Марсельский (ок. 290 г.) ‒ римский офицер, пострадавший за веру при императоре Максимиане. Открыто обличая язычество, он был арестован, проволочен по улицам Марселя и заключён в темницу, где обратил ко Христу трёх воинов (Лонгина, Александра и Фелициана), сразу казнённых." },
  { key: "08-03", name: "Сщмч. Петра Голубева, пресвитера", kind: "saint", desc: "Сщмч. Петр Голубев (1880-1938) родился в семье псаломщика Московской губернии. Окончив духовную семинарию, служил учителем, затем был рукоположен во священника." },
  { key: "08-03", name: "Обретение мощей св. Романа Медведя, исп., пресвитера", kind: "saint", desc: "Сщисп. Роман Медведь (1874-1937) ‒ выпускник Санкт-Петербургской духовной академии, духовный сын св. Иоанна Кронштадтского. С 1901 года ‒ священник, служил в Санкт-Петербурге и Севастополе (окормлял моряков)." },
  { key: "08-04", name: "Мироносицы равноап. Марии Магдалины", kind: "saint", desc: "Св. равноапостольная Мария Магдалина, исцелённая Христом от беснования (Лк.8:2), стала верной последовательницей Спасителя. Она присутствовала при Распятии, погребении и первой удостоилась увидеть Воскресшего Господа (Ин.20:11-18)." },
  { key: "08-04", name: "Перенесение мощей сщмч. Фоки, епископа Синопского", kind: "saint", desc: "Сщмч. Фока (†117) – епископ Синопский, обратил многих язычников к вере Христовой. При императоре Траяне принял мученическую смерть: после жестоких пыток был заперт в раскаленной бане." },
  { key: "08-04", name: "Прп. Корнилия Переяславского", kind: "saint", desc: "Прп. Корнилий Переяславльский (XVII в.) ‒ сын рязанского купца, в 15 лет ушел в Лукианову пустынь, затем подвизался в Борисоглебском монастыре. 30 лет хранил обет молчания, считаясь глухонемым." },
  { key: "08-04", name: "Сщмч. Михаила Накарякова, пресвитера", kind: "saint", desc: "Сщмч. Михаил Накаряков (1866-1918) ‒ священник Преображенского храма села Усолье Пермской губернии. Прославился милосердием, щедро помогал бедным. В 1918 году отказался совершать богослужения после ареста архиепископа Андроника, за что был арестован." },
  { key: "08-04", name: "сщмч. Алексия Ильинского, пресвитера", kind: "saint", desc: "Сщмч. Алексий Ильинский (1870-1931) ‒ священник из Тверской губернии, служивший в селе Спас. В марте 1931 года арестован по обвинению в антисоветской агитации и приговорён к 5 годам лагерей, заменённым ссылкой в Казахстан." },
  { key: "08-05", name: "Почаевской иконы Божией Матери", year: "1675", kind: "icon", desc: "История этой чудотворной иконы Богоматери неразрывно связана с Почаевским монастырём в честь Успения Пресвятой Богородицы (Украина) . На горе, где ныне расположена Успенская Почаевская лавра, в 1240 году поселились два инока." },
  { key: "08-05", name: "прав. воина Феодора Ушакова", kind: "saint", desc: "Св. праведный воин Феодор Ушаков (1745-1817) ‒ великий русский адмирал, не потерпевший ни одного поражения в морских сражениях. После военной службы посвятил жизнь молитве и благотворительности, построил храм в деревне Алексеевке, помогал нуждающимся." },
  { key: "08-05", name: "Сщмч. Аполлинария, епископа Равеннийского", kind: "saint", desc: "Сщмч. Аполлинарий Равеннийский (I в.) ‒ ученик апостола Петра, первый епископ Равенны. Проповедуя Евангелие, совершал многочисленные чудеса: исцелил слепого сына воина Иринея, супругу трибуна Феклу, немого Вонифатия." },
  { key: "08-05", name: "Сщмч. Михаила Троицкого, пресвитера", kind: "saint", desc: "Сщмч. Михаил Троицкий (1878-1938) служил священником в Подольском уезде Московской губернии. В 1937 году арестован по обвинению в \"антисоветской агитации\"." },
  { key: "08-05", name: "мч. Андрея Аргунова", kind: "saint", desc: "Мч. Андрей Аргунов (1904-1938) родился в подмосковной деревне Прудцы. Много лет был старостой в приходской церкви и пел в церковном хоре. Отказался вступать в колхоз по религиозным убеждениям, за что был лишён имущества." },
  { key: "08-05", name: "Всех скорбящих Радость (с грошиками)", year: "1888", kind: "saint", desc: "Икона Божией Матери «Всех скорбящих Радость» (с грошиками) прославилась в 1888 году в Петербурге, когда во время страшной грозы молния ударила в часовню, но находившаяся в ней святая икона Царицы Небесной, представляющая собой список с икон" },
  { key: "08-06", name: "Мц. Христины Тирской", kind: "saint", desc: "Мц. Христина Тирская (III в.) ‒ дочь правителя города Тира, с детства посвящённая в языческие жрицы. Через созерцание природы пришла к вере в Единого Бога." },
  { key: "08-06", name: "мчч. блгвв. кнн. Бориса", kind: "saint", desc: "Свв. благоверные князья Борис и Глеб (†1015) ‒ младшие сыновья св. князя Владимира. Воспитанные в христианской вере, они предпочли смерть междоусобной войне: Борис отказался бороться за престол против старшего брата Святополка, а Глеб смиренно принял смерть, зная о судьбе брата." },
  { key: "08-06", name: "Глеба, во Святом Крещении Романа и Давида", kind: "saint", desc: "Свв. благоверные князья Борис и Глеб (†1015) ‒ младшие сыновья св. князя Владимира. Воспитанные в христианской вере, они предпочли смерть междоусобной войне: Борис отказался бороться за престол против старшего брата Святополка, а Глеб смиренно принял смерть, зная о судьбе брата." },
  { key: "08-06", name: "Прп. Поликарпа, архимандрита Печерского", kind: "saint", desc: "Прп. Поликарп Печерский (XII в.) – инок Киево-Печерской лавры, с 1164 года игумен обители. Прославился как составитель житий печерских святых. Управлял монастырём до своей кончины в 1182 году." },
  { key: "08-06", name: "свт. Георгия, архиепископа Могилевского", kind: "saint", desc: "Свт. Георгий (Конисский) (1717-1795) родился в Нежине в дворянской семье. Окончив Киево-Могилянскую академию, принял монашество и стал преподавателем, позже ‒ ректором академии.", lifeId: "georgiy" },
  { key: "08-06", name: "обретение мощей прп. Далмата Исетского", kind: "saint", desc: "Основание Далматова монастыря в 1644 г. стало важной вехой в освоении Зауралья. Его создатель – бывший тобольский служилый человек Дмитрий Мокринский, принявший монашество с именем Далмат." },
  { key: "08-06", name: "Сщмч. Алфея Корбанского, диакона", kind: "saint", desc: "Сщмч. Алфей Корбанский (†1937) ‒ диакон из Вологды, сын священника. Окончил Вологодскую духовную семинарию, служил в Покровском храме, затем в церкви Рождества Пресвятой Богородицы после закрытия первого." },
  { key: "08-06", name: "свв. Николая Понгильского", kind: "saint", desc: "Сщисп. Николай Понгильский родился в 1879 году в семье священника Ярославской губернии. Окончив семинарию, стал полковым священником. После революции служил благочинным в Рыбинске, где был арестован в 1929 году за переписку с ссыльным епископом Рыбинским Вениамином." },
  { key: "08-06", name: "Иоанна Оленевского (Калинина) (1951), испп., пресвитеров", kind: "saint", desc: "Сщисп. Иоанн Оленевский (Иван Калинин) родился в 1854 году. С детства посвятил себя молитве, помогал в местной церкви. В 65 лет стал диаконом, позже ‒ священником." },
  { key: "08-07", name: "Успение праведной Анны, матери Пресвятой Богородицы", kind: "feast", desc: "Праведная Анна была дочерью Матфана и по отцу была из колена Левина, а по матери – из колена Иудина. Святой праведный Иоаким, ее муж, сын Варпафира, был потомком царя Давида, которому Бог обещал, что от семени его потомков родится Спаситель мира." },
  { key: "08-07", name: "свв. жен Олимпиады, диаконисы", kind: "saint", desc: "Св. Олимпиада, дочь сенатора, отказалась от брака, посвятив жизнь служению Богу. Унаследовав богатство, она щедро помогала нуждающимся, храмам и монастырям." },
  { key: "08-07", name: "прп. Евпраксии девы, Тавеннской", kind: "saint", desc: "Прп. Евпраксия, дочь константинопольского вельможи, в 7 лет осталась в египетском монастыре, отказавшись от знатного брака. Усердно подвизалась в посте, молитве и тяжёлых трудах, смиренно перенося искушения." },
  { key: "08-07", name: "прп. Макария Желтоводского, Унженского", kind: "saint", desc: "Прп. Макарий Желтоводский (1349-1444) в 12 лет тайно ушёл в Нижегородский Печерский монастырь, где принял постриг. Позже основал обитель на Желтом озере, крестил местных жителей, но после разорения татарами в 1439 году был вынужден переселиться в Галичские края к озеру Унжа, где основал новый монастырь." },
  { key: "08-07", name: "Память V Вселенского Собора", year: "553", kind: "feast", desc: "Пятый Вселенский Собор (Константинопольский II) был в Константинополе, при святом благоверном царе Юстиниане I (527–565), в 553 году, для решения вопроса о правоверии трех давно умерших епископов: Феодора Мопсуетского, Феодорита Кирского и " },
  { key: "08-07", name: "Сщмч. Николая Удинцева, пресвитера", kind: "saint", desc: "Сщмч. Николай Удинцев (1862-1918) родился в семье священника, работал учителем, затем принял сан. Служил в сёлах Екатеринбургской епархии, активно занимался просвещением и миссионерством среди старообрядцев." },
  { key: "08-07", name: "сщмч. Александра Сахарова, пресвитера", kind: "saint", desc: "Сщмч. Александр Сахаров (1873-1927), сын священника, окончил Санкт-Петербургскую Духовную академию и был рукоположен в сан священника. В 1924 году по доносу обновленцев был арестован за якобы антисоветские проповеди." },
  { key: "08-07", name: "св. Ираиды Тиховой, исп.", kind: "saint", desc: "Исповедница Ираида Тихова (1896-1967), происходившая из бедной крестьянской семьи, с детства мечтала стать учительницей. Окончив курсы в Угличе, с 1919 года преподавала в сельской школе, одновременно помогая репрессированному духовенству." },
  { key: "08-08", name: "Прп. Моисея Угрина, Печерского, в Ближних пещерах", kind: "saint", desc: "Прп. Моисей Угрин (†1043), венгр по происхождению, служил у св. блгв. князя Бориса, после его убийства бежал в Киев, но попал в польский плен. Богатая вдова, купив его, безуспешно пыталась склонить к браку." },
  { key: "08-08", name: "прмц. Параскевы Римской", kind: "saint", desc: "Прмц. Параскева, дочь благочестивых христиан, с юности посвятила себя Богу. После смерти родителей раздала имущество, приняла монашество и проповедовала язычникам." },
  { key: "08-08", name: "Сщмч. Сергия Стрельникова, пресвитера", kind: "saint", desc: "Сщмч. Сергий Стрельников (1887-1937), родившийся в семье диакона Вятской губернии, окончил духовную семинарию и с 1912 года посвятил себя пастырскому служению." },
  { key: "08-09", name: "Вмч. и целителя Пантелеимона", kind: "saint", desc: "Великомученик Пантелеимон (первоначально Пантолеон) родился в Никомидии в семье язычника Евсторгия и св. христианки Еввулы. Обучался врачебному искусству, под влиянием священника Ермолая принял христианство.", lifeId: "panteleimon" },
  { key: "08-09", name: "прп. Германа Аляскинского", kind: "saint", desc: "Прп. Герман Аляскинский (1757-1837) родился в Серпухове в купеческой семье. В 16 лет начал иноческий путь в Троице-Сергиевой пустыни под Петербургом, затем перешел на Валаам, где 15 лет подвизался в уединении." },
  { key: "08-09", name: "Блж. Николая Кочанова, Христа ради юродивого, Новгородского", kind: "saint", desc: "Блж. Николай Кочанов (XIV в.) – новгородский юродивый, происходивший из знатной семьи. Отказавшись от богатства, принял подвиг юродства, скитаясь по городу в рубище." },
  { key: "08-09", name: "свт. Иоасафа, митрополита Московского и всея Руси", kind: "saint", desc: "Свт. Иоасаф (Скрипицын) происходил из дворянского рода, принял постриг в Троице-Сергиевой Лавре, где стал игуменом в 1529 году. Он крестил будущего царя Ивана Грозного и постриг в монашество перед смертью его отца, великого князя Василия III." },
  { key: "08-09", name: "прп. Анфисы Мантинейской, исп., игумении, и 90 сестер ее", kind: "saint", desc: "Прп. Анфиса, игумения Мантинейская (VIII в.), подвизалась в Пафлагонии, в обители с 90 сестрами. Во время иконоборческих гонений императора Константина Копронима отказалась отречься от почитания икон, за что была подвергнута пыткам." },
  { key: "08-09", name: "Климента, архиепископа Охридского", kind: "saint", desc: "Св. Климент Охридский (IX-X вв.) ‒ продолжатель дела свв. равноапп. Кирилла и Мефодия, первый епископ, служивший на славянском языке. Организовал систему подготовки славянских священнослужителей." },
  { key: "08-09", name: "Горазда", kind: "saint", desc: "Равноап. Горазд Охридский (IX в.) ‒ ученик св. Мефодия, первый славянский архиепископ Великой Моравии. После смерти св. Мефодия возглавил борьбу за славянское богослужение против латинского духовенства." },
  { key: "08-09", name: "Ангеляра", kind: "saint", desc: "Равноап. Ангеляр Охридский (IX в.) ‒ один из учеников свв. Кирилла и Мефодия. После смерти св. Мефодия в 885 году подвергся гонениям вместе с другими славянскими священниками ‒ был заключён в темницу, избит и изгнан из Великой Моравии." },
  { key: "08-09", name: "Собор Смоленских святых", kind: "feast", desc: "Празднование было установлено по благословению патриарха Московского и всея Руси Пимена в 1983 году, в Неделю перед праздником Смоленской иконы Божией Матери Одигитрии." },
  { key: "08-09", name: "Амвросия (Гудко), епископа Сарапульского", kind: "saint", desc: "Сщмч. Амвросий (Гудко) родился в 1867 году в бедной мещанской семье. Окончив Санкт-Петербургскую духовную академию, принял монашество и посвятил жизнь миссионерству ‒ служил на Алтае, возглавлял Корейскую духовную миссию, был ректором семинарий." },
  { key: "08-09", name: "Платона Горных", kind: "saint", desc: "Сщмч. Платон Горных (1860?-1918) – выпускник Пермской духовной семинарии, служил священником в селах Екатеринбургской епархии. В 1918 году был арестован по ложному обвинению в контрреволюционной деятельности." },
  { key: "08-09", name: "Пантелеимона Богоявленского", kind: "saint", desc: "Сщмч. Пантелеймон Богоявленский (ок. 1881-1918) родился в семье псаломщика в Псковской губернии, рано осиротел. Окончив Псковскую духовную семинарию в 1903 году, начал служение псаломщиком на Талабских островах.", lifeId: "panteleimon" },
  { key: "08-09", name: "сщмч. Иоанна Соловьева, пресвитера", kind: "saint", desc: "Сщмч. Иоанн Соловьев (1894-1941) родился в семье псаломщика Рязанской губернии. Окончив духовную семинарию, служил псаломщиком, затем в 1917 году был рукоположен в диакона, а в 1930 году ‒ в священника." },
  { key: "08-10", name: "Смоленской иконы Божией Матери, именуемой «Одигитрия» (Путеводительница)", kind: "icon", desc: "Смоленская икона Божией Матери, именуемая &quot;Одигитрия&quot;, что значит &quot;Путеводительница&quot;, по Церковному преданию, была написана святым евангелистом Лукой во время земной жизни Пресвятой Богородицы." },
  { key: "08-10", name: "свт. Питирима, епископа Тамбовского", kind: "saint", desc: "Свт. Питирим Тамбовский (†1698), в миру Прокопий, родился в Вязьме. С юных лет посвятил себя Богу, став монахом в Вяземской Предтеченской обители. В 1685 году рукоположен во епископа Тамбовского." },
  { key: "08-10", name: "Собор святых Тамбовской митрополии", kind: "feast", desc: "Собор Тамбовских святых был утвержден по благословению святейшего патриарха Пимена в 1988 г. С тех пор были внесены изменения, потому что целый ряд новомучеников и новопрославленных святых – тамбовских уроженцев – был канонизирован для общероссийского почитания после 1988 года." },
  { key: "08-10", name: "Прп. Моисея чудотворца, Печерского, в Дальних пещерах", kind: "saint", desc: "Подвизался в XIII-XIV веках в Киево-Печерской лавре, нёс подвиг непрестанного псалмопения и коленопреклоненных молитв. Мощи почивают в Дальних пещерах монастыря." },
  { key: "08-10", name: "Иулиана", kind: "saint", desc: "Св. мученик Иулиан Далматский пострадал при императоре Антонине Пие (138–161). Прибыв в итальянскую провинцию Кампанию, он открыто исповедал себя христианином перед воинами правителя Флавиана." },
  { key: "08-10", name: "Евстафия", kind: "saint", desc: "Св. мученик Евстафий Анкирский, воин, был схвачен за исповедание христианства. Несмотря на пытки, он остался тверд в вере. Его били, просверлили пятки и, привязав веревкой, волокли к реке, где бросили в ящике в воду." },
  { key: "08-10", name: "Акакия", kind: "saint", desc: "Св. мученик Акакий отказался поклониться идолам, несмотря на пытки 3-х правителей. Его тело рвали железными орудиями, бросали в кипящую смолу и раскаленную печь, отдавали на растерзание зверям, но он оставался невредим." },
  { key: "08-10", name: "прп. Павла Ксиропотамского", kind: "saint", desc: "Прп. Павел Ксиропотамский, сын императора Михаила Куропалата, оставил мирскую славу и удалился на Афон, где принял постриг. Несмотря на ученость, он скрывал ее, посвятив жизнь подвижничеству." },
  { key: "08-10", name: "Сщмч. Николая Пономарева, диакона", kind: "saint", desc: "Сщмч. Николай Пономарев (1867–1918) служил псаломщиком в селе Шогрышском Ирбитского уезда, а в 1916 году был рукоположен в диакона. 28 июля (10 августа) 1918 года отца Николая отправили на принудительные работы на станцию Егоршино, где он был убит большевиками." },
  { key: "08-10", name: "прмч. Василия (Эрекаева), иеромонаха", kind: "saint", desc: "Иеромонах Василий (Эрекаев), родившийся в 1879 г. в крестьянской семье, принял постриг в Саровской пустыни и служил в Успенском храме села Старая Пичеморга." },
  { key: "08-10", name: "Анастасии", kind: "saint", desc: "Прмц. Анастасия (Камаева) родилась в 1879 г. в мордовской крестьянской семье, приняла постриг в Кадомском монастыре. После его закрытия жила в родном селе, сохраняя монашеский устав." },
  { key: "08-10", name: "Елены (Асташикиной), монахинь", kind: "saint", desc: "Прмц. Елена (Асташкина), родившаяся в 1878/1882 г. в крестьянской семье Пензенской губернии, с юности стремилась к монашеской жизни. В 1895 г. стала послушницей Покровского Шиханского монастыря, а позже перешла в Казанский Мокшанский монастырь." },
  { key: "08-10", name: "Арефы Ерёмкина", kind: "saint", desc: "Мч. Арефа Ерёмкин (1884-1937), крестьянин из села Красивка Пензенской губернии, был арестован в 1937 г. за \"антисоветскую агитацию\" – обвинялся в проведении религиозных бесед и призыве не вступать в колхозы." },
  { key: "08-10", name: "Иоанна Ломакина", kind: "saint", desc: "Мч. Иоанн (Ломакин, 1884-1937) ‒ крестьянин из Мордовии, сохранявший единоличное хозяйство во время коллективизации. В 1937 году арестован за участие \"в религиозной контрреволюционной организации, по заданию которой проводил антиколхозную агитацию\" и расстрелян 10 августа, не признав вины." },
  { key: "08-11", name: "Мч. Каллиника Киликийского", kind: "saint", desc: "Св. мч. Каллиник (III-IV вв.), родом из Киликии, с детства воспитанный в христианской вере, отправился проповедовать Евангелие язычникам. В Анкире его схватили и привели к правителю Сакердону, который требовал отречься от Христа." },
  { key: "08-11", name: "мч. Даниила Черкасского", kind: "saint", desc: "Мч. Даниил Кушнир (XVIII в.) пострадал за веру во время гонений униатов. В 1766 году жители села Млиев решили вернуться в Православие, спрятав священнические облачения, книги и сосуды." },
  { key: "08-11", name: "мц. Серафимы девы", kind: "saint", desc: "Св. мц. Серафима (†138), антиохийская дева, жила в Риме при императоре Адриане. Во время гонений её арестовали и пытались заставить отречься от веры. Когда два юноши попытались её обесчестить, по молитве святой произошло землетрясение, парализовавшее их." },
  { key: "08-11", name: "мц. Феодотии и трех чад ее", kind: "saint", desc: "Мц. Феодотия Никейская († 304) ‒ молодая вдова из Фессалоник, помогавшая св. Анастасии Узорешительнице. Обвинённая перед императором Диоклетианом, была выпрошена сановником Левкадием, но отказалась от брака и отречения от Христа." },
  { key: "08-11", name: "свт. Лупа, епископа Труаского", kind: "saint", desc: "Свт. Луп (383-479) ‒ епископ Труа, происходивший из знатной галло-римской семьи. После 6 лет брака принял монашество в Леринском монастыре, а около 426 года стал епископом." },
  { key: "08-11", name: "прмч. Михаила Савваита, черноризца", kind: "saint", desc: "Ученик святого Феодора Эдесского. Раздав имущество, отправился в Иерусалим, поселился в лавре св. Саввы. При продаже монастырских изделий попал к мусульманской царице Сеиде." },
  { key: "08-11", name: "мч. Евстафия Мцхетского (589)", kind: "saint", desc: "Св. мч. Евстафий Мцхетский (†589) ‒ перс-огнепоклонник, принявший христианство в Грузии. Будучи сапожником в Мцхете, он обратился ко Христу, крестился и вёл благочестивую жизнь." },
  { key: "08-11", name: "Серафима", kind: "saint", desc: "Прмчч. Анатолий (Смирнов), Серафим (Богословский) и Феогност (Пивоваров) ‒ глинские подвижники, переведенные в начале XX века в Свято-Троицкий Иссык-Кульский монастырь." },
  { key: "08-11", name: "Феогноста (Пивоварова)", kind: "saint", desc: "Прмчч. Анатолий (Смирнов), Серафим (Богословский) и Феогност (Пивоваров) ‒ глинские подвижники, переведенные в начале XX века в Свято-Троицкий Иссык-Кульский монастырь." },
  { key: "08-11", name: "прмч. Анатолия (Смирнова), иеромонаха", kind: "saint", desc: "Прмч. Анатолий (Смирнов) – глинский подвижник, регент и композитор. В начале XX века был направлен в Свято-Троицкий миссионерский монастырь на Иссык-Куле." },
  { key: "08-11", name: "сщмч. Алексия Красновского, пресвитера,", kind: "saint", desc: "Сщмч. Алексий Красновский (1886-1938) ‒ священник Московской епархии, служил в храмах Орехово-Зуевского и Наро-Фоминского районов. В 1931 году арестован за невыполнение сельхозналога, но вскоре освобожден." },
  { key: "08-11", name: "прмч. Пахомия (Русина), иеромонаха", kind: "saint", desc: "Прмч. Пахомий (Русин, 1880-1938) ‒ иеромонах, уроженец Курской губернии. В 1910 году переселился в Казахстан, где стал насельником Свято-Троицкого Иссык-Кульского монастыря." },
  { key: "08-12", name: "Силуана", kind: "saint", desc: "Апостол от 70-ти Силуан был сподвижником апостолов Петра и Павла, упомянут в 1Пет.5:12 как верный брат. Проповедовал Евангелие, стал епископом Солуни (Фессалоник), где принял мученическую кончину." },
  { key: "08-12", name: "Крискента", kind: "saint", desc: "Апостол от 70-ти Крискент, упомянутый апостолом Павлом (2Тим.4:10), проповедовал в Галатии, где стал епископом, а затем пошел с проповедью в Галлию. Вернувшись в Галатию, принял мученическую смерть при императоре Траяне (98-117 гг.)." },
  { key: "08-12", name: "Епенета", kind: "saint", desc: "Апостол от 70-ти Епенет, названный апостолом Павлом \"начатком Ахаии для Христа\" (Рим.16:5), был первым епископом Карфагена. Он ревностно проповедовал Евангелие, став основателем и устроителем Карфагенской Церкви." },
  { key: "08-12", name: "Андроника", kind: "saint", desc: "Ап. Андроник и св. Иуния – сродники апостола Павла (Рим.16:7), одни из первых уверовавших во Христа. Ап. Андроник стал епископом Паннонии, но их миссия вышла далеко за пределы епархии." },
  { key: "08-12", name: "мч. Иоанна Воина", kind: "saint", desc: "Св. мч. Иоанн Воин служил в войске императора-отступника Юлиана (361-363 гг.), тайно помогая христианам: освобождал арестованных, предупреждал об опасности." },
  { key: "08-12", name: "прп. Анатолия II Оптинского, Младшего", kind: "saint", desc: "Прп. Анатолий Оптинский (Потапов) (1855-1922) ‒ один из последних оптинских старцев. С юных лет стремился к духовной жизни, но мать не отпускала его в монастырь, и только после ее смерти, в 1885 г., калужский приказчик Александр Потапов пришел в Оптину пустынь, став келейником прп." },
  { key: "08-12", name: "Обретение мощей прп. Германа Соловецкого", kind: "saint", desc: "Прп. Герман Соловецкий – один из основателей Соловецкого монастыря. В 1429 году вместе с прп. Савватием поселился на Соловецких островах, а в 1436 году с прп." },
  { key: "08-12", name: "Собор Самарских святых", kind: "feast", desc: "Список святых дан в соответствии с документом «Поименные списки местных соборов святых, почитаемых в Самоуправляемых Церквах, Экзархатах, Митрополичьих округах, митрополиях и епархиях» , утвержденным на заседании Священного Синода 16 мая 2023 года (журнал № 31)." },
  { key: "08-12", name: "прп. Ангелины, деспотисы Сербской", kind: "saint", desc: "Прп. Ангелина Сербская (Бранкович), дочь албанского князя и супруга св. сербского короля Стефана, разделила с мужем изгнание, воспитав сыновей Максима и Иоанна в христианском благочестии." },
  { key: "08-12", name: "Сщмч. Иоанна Плотникова, диакона", kind: "saint", desc: "Сщмч. Иоанн Плотников (1864-1918) ‒ диакон Сретенского храма в Старопышминске (Свердловская обл.). 30 июня 1918 года был зверски убит большевиками на горе Высокой как представитель \"реакционного класса\"." },
  { key: "08-13", name: "Предпразднство Изнесения Честных Древ Животворящего Креста Господня", kind: "feast", desc: "В греческом часослове 1897 года так объясняется происхождение этого праздника: &quot;По причине болезней, весьма часто бывавших в августе, издревле утвердился в Константинополе обычай износить Честное Древо Креста на дороги и улицы для освящения мест и в отвращение болезней." },
  { key: "08-13", name: "Прав. Евдокима Каппадокиянина", kind: "saint", desc: "Праведный Евдоким (IX в.), каппадокиец, происходил из знатного рода и был назначен правителем Харсианской области. Дав обет безбрачия, он посвятил жизнь служению Богу и ближним, отличаясь милосердием и справедливостью." },
  { key: "08-13", name: "Мц. Иулитты Кесарийской (Каппадокийской)", kind: "saint", desc: "Св. мц. Иулитта пострадала в Кесарии Каппадокийской во время гонений Диоклитиана (304-305 гг.). Лишившись имущества из-за доноса о своей христианской вере, она отвергла предложение отречься от Христа взамен на восстановление справедливости." },
  { key: "08-13", name: "свт. Германа, епископа Осерского", kind: "saint", desc: "Свт. Герман Осерский (†448) – епископ галльского города Осера, прославившийся милосердием. В 429 и 440 годах дважды посещал Британию для борьбы с пелагианской ересью, где также помог бриттам одержать победу над врагами." },
  { key: "08-13", name: "прмч. Дионисия Ватопедского", kind: "saint", desc: "Прмч. Дионисий Ватопедский (†1822) ‒ афонский монах, пострадавший на Крите. В 1822 году, сопровождая Пояс Пресвятой Богородицы во время эпидемии, был захвачен турками." },
  { key: "08-13", name: "Сщмч. Вениамина (Казанского), митрополита Петроградского", kind: "saint", desc: "Сщмч. Вениамин (Казанский, 1873-1922) ‒ митрополит Петроградский, родился в семье священника, окончил Санкт-Петербургскую духовную академию. В 1910 году хиротонисан во епископа Гдовского, в 1917 году избран митрополитом Петроградским." },
  { key: "08-13", name: "и с ним прмч. Сергия (Шеина), архимандрита", kind: "saint", desc: "Прмч. архимандрит Сергий (Шеин, 1870-1922) ‒ дворянин, выпускник Училища правоведения, бывший член Государственной думы. В 1920 году принял монашество, стал архимандритом и настоятелем Троицкого подворья в Петрограде." },
  { key: "08-13", name: "Юрия Новицкого", kind: "saint", desc: "Мч. Юрий Новицкий (1882-1922) ‒ профессор права, общественный деятель. Как председатель Общества православных приходов и профессиональный юрист помогал митрополиту Петроградскому Вениамину (Казанскому) вести переговоры с советской властью." },
  { key: "08-13", name: "Иоанна Ковшарова", kind: "saint", desc: "Мч. Иоанн Ковшаров (1878-1922) ‒ юрист, бывший присяжный поверенный, юрисконсульт Александро-Невской лавры. В 1922 году арестован по «делу о сопротивлении изъятию церковных ценностей»." },
  { key: "08-13", name: "мч. Максима Румянцева", kind: "saint", desc: "Мч. Максим Румянцев (†1928) ‒ уроженец Костромской губернии. После 30 лет странствий вернулся на родину, приняв подвиг юродства: ходил босиком, носил одну одежду, избегал удобств." },
  { key: "08-13", name: "сщмч. Владимира Холодковского, пресвитера", kind: "saint", desc: "Сщмч. Владимир Холодковский (1895-1937) ‒ священник из Пермской губернии. В годы гражданской войны пытался примирить враждующие стороны, следуя наставлениям Патриарха Тихона." },
  { key: "08-13", name: "сщмч. Иоанна Румянцева, пресвитера", kind: "saint", desc: "Сщмч. Иоанн Румянцев (1889-1941) ‒ священник из Костромской губернии. Окончил духовное училище, служил псаломщиком, затем диаконом в Макариев-Решемском монастыре." },
  { key: "08-13", name: "св. Константина Разумова, исп., пресвитера", kind: "saint", desc: "Сщисп. Константин Разумов (1869 – после 1937) родился в Костромской губернии. В 1904 году был рукоположен в сан священника к Успенскому монастырю города Кинешмы." },
  { key: "08-13", name: "мц. Анны Серовой", kind: "saint", desc: "Мц. Анна Серова родилась в крестьянской семье в Костромской губернии, в 1920-х работала на фабрике в Кинешме. Была арестована вместе со священником Константином Разумовым и другими верующими за участие в церковной жизни." },
  { key: "08-14", name: "Изнесение Честных Древ Животворящего Креста Господня", kind: "feast", desc: "В греческом часослове 1897 года так объясняется происхождение этого праздника: &quot;По причине болезней, весьма часто бывавших в августе, издревле утвердился в Константинополе обычай износить Честное Древо Креста на дороги и улицы для освящения мест и в отвращение болезней." },
  { key: "08-14", name: "Празднество Всемилостивому Спасу и Пресвятой Богородице", year: "1164", kind: "feast", desc: "Празднество Всемилостивому Спасу и Пресвятой Богородице установлено по случаю знамений от икон Спасителя, Пресвятой Богородицы и Честного Креста во время сражений святого благоверного князя Андрея Боголюбского (1157–1174) с волжскими булгарами в 1164 году." },
  { key: "08-14", name: "Обретение мощей прп. Софии Суздальской", kind: "saint", desc: "Прп. София, в миру великая княгиня Соломония, первая жена Василия III, была насильно пострижена в монахини (1525) после 20 лет бездетного брака и сослана под стражу в Суздальский Покровский монастырь, где подвигами изгнала из сердца мирские помыслы, всецело посвятив себя Богу." },
  { key: "08-14", name: "Сщмч. Димитрия Павского, пресвитера", kind: "saint", desc: "Сщмч. Димитрий Павский (1874-1937) родился в Тверской губернии в семье священника. Окончив Казанскую духовную академию, служил в Минской епархии, где возглавлял церковноприходские школы и преподавал в семинарии." },
  { key: "08-15", name: "Перенесение из Иерусалима в Константинополь мощей первомученика Стеф а на, архидиакона", year: "ок. 428", kind: "feast", desc: "Святой апостол первомученик и архидиакон Стефан был старшим среди семи диаконов, поставленных самими апостолами, поэтому его называют архидиаконом. Он был христианским первомучеником и пострадал за Христа в возрасте около 30 лет." },
  { key: "08-15", name: "обретение мощей правв. Никодима", kind: "saint", desc: "Прав. Никодим, тайный ученик Христа, был фарисеем и членом синедриона. Он защищал Христа перед первосвященниками (Ин.7:50-51) и участвовал в Его погребении (Ин.19:39)." },
  { key: "08-15", name: "Гамалиила", kind: "saint", desc: "Праведный Гамалиил († ок. 50), еврейский законоучитель, фарисей. В Новом Завете о нём говорится как о «законоучителе, уважаемом всем народом» (Деян.5:34), выступившем перед синедрионом с речью в защиту апостолов (Деян.5:34-40)." },
  { key: "08-15", name: "и сына его Авива", kind: "saint", desc: "Праведный Авив Иерусалимский (I в.) ‒ сын праведного законоучителя Гамалиила. Принял крещение вместе с отцом. Был погребён в гробнице в Кафаргамале рядом с первомучеником Стефаном, праведным Никодимом и своим отцом Гамалиилом." },
  { key: "08-15", name: "блж. Василия Московского, Христа ради юродивого, чудотворца", kind: "saint", desc: "Блж. Василий, Христа ради юродивый, Московский чудотворец (1468-1557). Родился в Москве, с 16 лет начал путь юродства, ходя нагим и босым в любую погоду." },
  { key: "08-15", name: "Блж. Василия Спасо-Кубенского (Каменского)", kind: "saint", desc: "Блж. Василий Каменский (XVII-XVIII вв.) – Христа ради юродивый, инок Спасо-Каменного монастыря (недалеко от Вологды). Прославился аскетическими подвигами, носил тяжелые железные вериги." },
  { key: "08-15", name: "сщмч. Стефана I, папы Римского, и иже с ним", kind: "saint", desc: "Сщмч. Стефан, папа Римский, пострадал при императоре Валериане в 257 году. Возглавлял Римскую кафедру с 253 года, активно противостоя ереси Новата. Во время гонений тайно крестил многих." },
  { key: "08-15", name: "Мч. Афанасия Жуланова", kind: "saint", desc: "Мч. Афанасий Жуланов (1890-1918) – псаломщик, происходивший из крестьянской семьи. Перед мученической кончиной служил в Афанасие-Кирилловской церкви в селе Бисертское Пермской губернии." },
  { key: "08-15", name: "прмч. Платона (Колегова), иеромонаха", kind: "saint", desc: "Прмч. Платон (Колегов, 1865-1937) – уроженец Пермской губернии, иеромонах Ульяновского Троице-Стефановского монастыря. В 1919 году арестован за \"пособничество белым\", отбыл 5 лет лагерей." },
  { key: "08-15", name: "Ачаирская", year: "XXI", kind: "saint", desc: "По благословению Высокопреосвященнейшего Феодосия, митрополита Омского и Тарского, в 2002 г. омским иконописцем Геннадием Адаевым был написан этот образ." },
  { key: "08-16", name: "Исаакия", kind: "saint", desc: "Св. Исаакий Далматский жил в IV веке, был монахом и основателем Далматского монастыря под Константинополем. Прославился обличением ереси арианства и смелым противостоянием императору-еретику Валенту." },
  { key: "08-16", name: "прп. Антония Римлянина, Новгородского чудотворца", kind: "saint", desc: "Прп. Антоний Римлянин (1067-1147) – уроженец Рима, раздавший наследство и принявший монашество. После гонений на православных чудесным образом приплыл на камне по морю к Новгороду (1105), где основал Рождество-Богородичный монастырь." },
  { key: "08-16", name: "Мч. Раждена Перса, первомученика Грузинского (457)", kind: "saint", desc: "Мч. Ражден Перс (†457) – знатный перс-зороастриец, воспитатель царевны Балендухты. Переселившись в Грузию, принял христианство. Во время персидского нашествия возглавил оборону столицы." },
  { key: "08-16", name: "прп. Космы отшельника", kind: "saint", desc: "Прп. Косма Фаранский (VI в.) – палестинский отшельник, известный строгим подвижничеством и глубоким знанием Священного Писания. Скончался в Антиохии, где был погребён патриархом." },
  { key: "08-16", name: "Сщмч. Вячеслава Луканина, диакона", kind: "saint", desc: "Сщмч. Вячеслав Луканин (1882-1918) – уроженец Перми, сын священника, с детства посвятивший себя церковному служению. Обладая прекрасным голосом, стал регентом, затем диаконом." },
  { key: "08-16", name: "сщмч. Николая Померанцева, пресвитера", kind: "saint", desc: "Сщмч. Николай Померанцев (1881-1938) – уроженец Московской губернии, сын псаломщика. Окончив Московскую духовную семинарию, служил псаломщиком, с 1917 года – священником в подмосковных храмах." },
  { key: "08-17", name: "прав. Алексия Бортсурманского, пресвитера", kind: "saint", desc: "Праведный Алексий Бортсурманский (1762-1848) – священник села Бортсурманы Симбирской губернии, прошедший путь от грешника к великому подвижнику. После видения Ангела с Чашей (1796) полностью изменил жизнь, ежедневно совершая Литургию и соблюдая строгий молитвенный устав." },
  { key: "08-17", name: "Прмц. Евдокии (Ии) Римляныни", kind: "saint", desc: "Св. мц. Ия (IV в.) – одна из 9000 христиан, захваченных персидским царем Шапуром II. Отказалась отречься от Христа, несмотря на жестокие пытки. После мучений в темнице была обезглавлена." },
  { key: "08-17", name: "мч. Елевферия Византийского", kind: "saint", desc: "Св. мч. Елевферий Кувикуларий (IV в.) – знатный византийский вельможа, принявший христианство. Несмотря на высокое положение, посвятил жизнь молитве и добрым делам." },
  { key: "08-17", name: "свт. Арсения Элассонского, архиепископа", kind: "saint", desc: "Свт. Арсений Элассонский (1550–1625) родился в Фессалии, принял постриг на Афоне. В 1588 году прибыл в Москву в составе Константинопольского посольства и остался на Руси." },
  { key: "08-17", name: "Михаила (Жука), иеромонаха", kind: "saint", desc: "Прмч. Михаил (Жук, 1872-1937) – уроженец Львовщины, из крестьян. После Первой мировой войны оказался в России, в 1924 году стал послушником Спасо-Преображенского монастыря под Краснослободском." },
  { key: "08-17", name: "Казанская (Пензенская)", year: "1717", kind: "saint", desc: "Казанская икона Божией Матери была пожалована царем Алексеем Михайловичем (1645–1676) в благословение городу Пензе при его основании в 1666 году. От Москвы до самой Пензы образ несли на руках и поместили в городскую соборную церковь." },
  { key: "08-18", name: "Предпразднство Преображения Господня", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-18", name: "Мч. Евсигния Антиохийского", kind: "saint", desc: "Мч. Евсигний Антиохийский (III–IV вв.) – римский воин, служивший шести императорам от Диоклетиана до Константина Великого. В старости, при Юлиане Отступнике (362 г.), 110-летний старец был казнён за исповедание христианской веры и обличение императора." },
  { key: "08-18", name: "Прмч. Иова Ущельского", kind: "saint", desc: "Прп. Иов Ущельский (†1628) – соловецкий инок, основатель монастыря на реке Мезень. 5 августа 1628 года был зверски убит разбойниками, искавшими монастырские сокровища." },
  { key: "08-18", name: "Анфира", kind: "saint", desc: "Сщмч. Анфир Римский (†236) – греческий епископ, ставший папой Римским. Избран в ноябре 235 года, но через 40 дней арестован императором Максимином Фракианцем." },
  { key: "08-18", name: "мч. Понтия Римлянина", kind: "saint", desc: "Мч. Понтий Римлянин (†257) – сын римского сенатора, обращенный в христианство папой Понтианом. Будучи сенатором, способствовал обращению императора Филиппа Араба." },
  { key: "08-18", name: "Кантидия", kind: "saint", desc: "Мученик Кантидиан Египетский вместе со святым мучеником Кантидием (Кандидием) были побиты камнями в Египте. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите к" },
  { key: "08-18", name: "Кантидиана", kind: "saint", desc: "Мученик Кантидиан Египетский вместе со святым мучеником Кантидием (Кандидием) были побиты камнями в Египте. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите к" },
  { key: "08-18", name: "Сивела, в Египте", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "08-18", name: "прав. Нонны Назианзской, диаконисы, матери свт. Григория Богослова", kind: "saint", desc: "Праведная Нонна Назианзинская (IV в.) – мать свт. Григория Богослова, супруга епископа Григория Старшего. Родилась в христианской семье, вышла замуж за язычника и молитвами обратила его ко Христу." },
  { key: "08-18", name: "Сщмч. Стефана Хитрова, пресвитера", kind: "saint", desc: "Сщмч. Стефан Хитров (1851-1920) – священник Екатеринбургской епархии, служивший в сельских храмах. Во время Гражданской войны оказался в Белой армии, служил лазаретным священником." },
  { key: "08-18", name: "Евдокии Шейковой", kind: "saint", desc: "Крестьянка из с. Пуза (ныне Суворово) Нижегородской губ. С 20 лет, будучи парализованной, вела строгую молитвенную жизнь, неся подвиг юродства. Обладала даром прозорливости и исцелений." },
  { key: "08-18", name: "Дарии Улыбиной", kind: "saint", desc: "Келейница св. Евдокии Шейковой в с. Пуза (ныне Суворово) Нижегородской губ. С 1916 года подвизалась у парализованной наставницы, отличаясь смирением и благочестием." },
  { key: "08-18", name: "Дарии Тимагиной", kind: "saint", desc: "Крестьянка из Нижегородской губ. В 15 лет, несмотря на противодействие родителей (дважды сбегала от насильной выдачи замуж), стала келейницей парализованной подвижницы Евдокии Шейковой." },
  { key: "08-18", name: "Марии Неизвестной", kind: "saint", desc: "Одна из 3-х келейниц мц. Евдокии Шейковой в с. Пуза (Нижегородская губ.). 18 августа 1919 г., когда Евдокию приговорили к расстрелу по ложному обвинению, Мария добровольно избрала смерть вместе с наставницей и сёстрами (Дариями Улыбиной и Тимагиной)." },
  { key: "08-19", name: "Преображение Господа Бога и Спаса нашего Иисуса Христа", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-19", name: "Сщмч. Николая Заварина, пресвитера", kind: "saint", desc: "Сщмч. Николай Заварин (1878-1937) – уроженец Вологодской губернии, сын священника. Служил учителем, затем псаломщиком, диаконом и с 1926 года – священником." },
  { key: "08-20", name: "Попразднство Преображения Господня", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-20", name: "Прмч. Дометия Персянина, иеродиакона, и двух учеников его", kind: "saint", desc: "Прмч. Дометий Персиянин (IV в.) – перс по происхождению, обращённый в христианство. Принял монашество в Месопотамии, затем подвизался под руководством строгого аскета архимандрита Нурвела." },
  { key: "08-20", name: "Обретение мощей свт. Митрофана, в схиме Макария, епископа Воронежского", kind: "saint", desc: "Свт. Митрофан Воронежский (1623-1703) – выдающийся архипастырь XVII века. Родился во Владимирской земле, 40 лет прожил в миру, овдовев, принял монашество." },
  { key: "08-20", name: "прп. Антония Оптинского", kind: "saint", desc: "Прп. Антоний Оптинский (Путилов, 1795-1865) родился в благочестивой купеческой семье, с детства стремился к монашеству. В 1820 году принял постриг в Рославльских лесах, где подвизался его брат – будущий прп." },
  { key: "08-20", name: "Прп. Пимена Многоболезненного, Печерского, в Ближних пещерах", kind: "saint", desc: "Прп. Пимен Многоболезненный (†1110) – Киево-Печерский подвижник, прославившийся терпением тяжких болезней. С детства страдая недугом, он умолил родителей отнести его в Киево-Печерскую обитель, где ангелы чудесно постригли его в монашество." },
  { key: "08-20", name: "прп. Пимена, игумена, постника Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Пимен постник (XII в.) – Киево-Печерский подвижник, известный крайним воздержанием (питался раз в неделю) при постоянном физическом труде и непрестанной молитве." },
  { key: "08-20", name: "прп. Меркурия Печерского, епископа Смоленского, в Ближних пещерах", kind: "saint", desc: "Прп. Меркурий (†1239), епископ Смоленский, был иноком Киево-Печерской лавры до епископства. Принял мученическую смерть во время Батыева нашествия. Чудом его мощи приплыли по Днепру в Киев, где почивают в Ближних пещерах Лавры." },
  { key: "08-20", name: "Марина", kind: "saint", desc: "Мч. Марин пострадал за Христа, разрушив языческий жертвенник и поправ жертвенные дары. После жестоких пыток был обезглавлен. Святой Марин, вдохновленный пламенной любовью ко Христу Спасителю, на одном из праздников в идольском капище разрушил жертвенник, стал топтать ногами жертвы и при всех исповедал себя христианином." },
  { key: "08-20", name: "Астерия", kind: "saint", desc: "Мч. Астерий (†260) – римский сенатор-христианин. В Кесарии Филипповой он разоблачил языческое чудо, изгнав беса из идола молитвой. Похоронил казнённого мученика Марина, за что сам был обезглавлен." },
  { key: "08-20", name: "прп. Ора Фиваидского", kind: "saint", desc: "Прп. Ор Фиваидский (IV в.) – египетский подвижник, проведший молодость в полном уединении. После ангельского видения стал духовным наставником, основав обители с 1000 монахов." },
  { key: "08-20", name: "прмц. Потамии чудотворицы", kind: "saint", desc: "Преподобномученица Потамия чудотворица скончалась от меча. Иногда в месяцесловах ошибочно именуется преподобным Потамием чудотворцем. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, " },
  { key: "08-20", name: "прп. Феодосия Нового", kind: "saint", desc: "Прп. Феодосий Новый (IX–X), родившийся в Афинах, с детства стремился к духовной жизни. После смерти родителей раздал имущество и стал монахом. Прославился даром исцелений и духовной прозорливости." },
  { key: "08-20", name: "свт. Иерофея Венгерского, епископа", kind: "saint", desc: "Свт. Иерофей, епископ Венгерский, был направлен из Константинополя в X веке для проповеди христианства среди венгров. Он успешно обращал местное население, особенно в регионе Тисы, где археологи находят византийские кресты и остатки церквей." },
  { key: "08-20", name: "св. Стефана I, короля Венгрии", kind: "saint", desc: "Св. Стефан (ок. 970–1038) ‒ первый король Венгрии. Крещен в детстве. Глубоко христианизировал страну, основав 10 епархий, монастыри и церкви и создав законы по евангельским принципам." },
  { key: "08-21", name: "Попразднство Преображения Господня", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-21", name: "Свт. Емилиана исп., епископа Кизического", kind: "saint", desc: "Исповедник Емилиан, епископ Кизический (IX в.). В 815 году при императоре-иконоборце Льве Армянине мужественно отказался отвергнуть почитание икон. Был сослан в заточение, где и скончался." },
  { key: "08-21", name: "Прп. Григория, иконописца Печерского, в Ближних пещерах", kind: "icon", desc: "Прп. Григорий Печерский – иконописец XII века, сподвижник прп. Алипия Печерского. Написал много чудотворных икон для русских храмов. Вероятно, был среди византийских мастеров, приглашённых для росписи Успенского собора Киево-Печерской лавры." },
  { key: "08-21", name: "Перенесение мощей прпп. Зосимы", kind: "saint", desc: "Прп. Зосима Соловецкий (XV в.) вместе с прп. Германом поселился на пустынном острове около 1436 года, где основал Соловецкий монастырь. Став игуменом, ввел строгое общежитие, перенес на Соловки мощи прп." },
  { key: "08-21", name: "Савватия Соловецких", kind: "saint", desc: "Прп. Савватий Соловецкий – первоначальник Соловецкой обители. Принял постриг в Кирилло-Белоезерском монастыре, затем подвизался на Валааме, но, избегая мирской славы, отправился на необитаемый Соловецкий остров (1429 г.)." },
  { key: "08-21", name: "Германа Соловецких", kind: "saint", desc: "Прп. Герман Соловецкий – один из основателей Соловецкого монастыря. В 1429 году вместе с прп. Савватием поселился на Соловецких островах, а в 1436 году с прп." },
  { key: "08-21", name: "свт. Мирона чудотворца, епископа Критского", kind: "saint", desc: "Свт. Мирон Критский (III-IV вв.) – чудотворец, происходил из земледельцев. Прославился необыкновенным милосердием – однажды помог ворам унести украденное у него зерно, чем обратил их к честной жизни." },
  { key: "08-21", name: "прп. Григория Синаита", kind: "saint", desc: "Прп. Григорий Синаит (1268-1310/1346) родился в Малой Азии. После плена у агарян принял монашество на Кипре, затем подвизался на Синае и Афоне, где изучал традиции монашеской жизни." },
  { key: "08-21", name: "Николая Прозорова", kind: "saint", desc: "Сщмч. Николай Прозоров (1897-1930) – уроженец Пензенской губернии, сын пономаря. Окончив духовное училище, участвовал в Первой мировой войне (штабс-капитан)." },
  { key: "08-21", name: "Сергия Тихомирова", kind: "saint", desc: "Сщмч. Сергий Тихомиров (†1930) – петербургский священник. Служил в нескольких храмах, был духовником интеллигенции. После 1927 года присоединился к \"иосифлянскому\" движению, служил в соборе Воскресения Христова (\"Спас-на-Крови\")." },
  { key: "08-21", name: "сщмч. Николая Шумкова, пресвитера", kind: "saint", desc: "Сщмч. Николай Шумков (1886-1937) – уроженец Вологодской губернии. С 1913 года нёс диаконское, затем священническое служение в Коми крае. Трижды подвергался репрессиям: в 1929 году – за \"неуплату налогов\", в 1931 – по абсурдному обвинению в \"невыполнении мясопоставок\", в 1937 – за \"антисоветскую агитацию\"." },
  { key: "08-21", name: "сщмч. Никодима (Кроткова), архиепископа Костромского", kind: "saint", desc: "Сщмч. Никодим (Кротков) (1868-1938) – архиепископ Костромской и Галичский. Управлял Чигиринской (1911-1917, 1918-1921), Петровской (1917-1918) и Симферопольской (1921-1924) кафедрами." },
  { key: "08-21", name: "Толгская", year: "1314", kind: "saint", desc: "В 1314 году, когда Ярославлем владел князь Давид Федорович, здешний епископ Прохор (в схиме Трифон) возвращался из Верхнего Заволжья, где впоследствии возник Кирилло-Белозерский монастырь, в свой кафедральный город." },
  { key: "08-22", name: "Попразднство Преображения Господня", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-22", name: "Ап. Матфия", kind: "saint", desc: "Ап. Матфий, ученик Христа, был избран по жребию вместо Иуды Искариота в число 12 апостолов. Проповедовал в Иудее, Сирии и Малой Азии, совершая чудеса: остался невредим после отравленного питья, земля поглотила его гонителей." },
  { key: "08-22", name: "Собор Соловецких святых", kind: "feast", desc: "Собор Соловецких святых – празднование Русской Православной Церкви в честь святых Соловецкой обители (9 / 22 августа). Прославленные подвижники, пострадавшие в обители во времена безбожных гонений XX века, составляют особый Собор новомучеников и исповедников Соловецких ." },
  { key: "08-22", name: "Свт. Филарета, архиепископа Черниговского", kind: "saint", desc: "Свт. Филарет (Гумилевский) (1805-1866) – архиепископ Черниговский, выдающийся церковный деятель XIX века. Родился в семье священника Тамбовской губернии." },
  { key: "08-22", name: "мч. Антония Александрийского", kind: "saint", desc: "Мч. Антоний пострадал в Александрии. После жестоких пыток (подвешивание на дереве и строгание железом) был приговорён к сожжению. На костре проповедовал собравшимся о спасении души." },
  { key: "08-22", name: "прп. Псоя Египетского", kind: "saint", desc: "Прп. Псой Египетский (IV в.), ученик прп. Пахомия Великого. Подвизался в египетской пустыне. Преподобный Псой был ученик преподобного Пахомия Великого (память 15 мая) и подвизался в IV веке в Египетской пустыне." },
  { key: "08-22", name: "Прмц. Маргариты (Гунаропуло), игумении", kind: "saint", desc: "Прмц. игумения Маргарита (Гунаропуло) (1865-1918) – гречанка по происхождению. В 1917 году назначена настоятельницей Мензелинского Пророко-Ильинского монастыря." },
  { key: "08-23", name: "Попразднство Преображения Господня", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-23", name: "блж. Лаврентия, Христа ради юродивого, Калужского", kind: "saint", desc: "Блж. Лаврентий, Христа ради юродивый, жил в XVI веке близ Калуги при лесном храме в честь Рождества Христова. Зимой и летом ходил босой, в рубашке и тулупе, еще при жизни прославившись благодатными дарованиями." },
  { key: "08-23", name: "Собор новомучеников и исповедников Соловецких", kind: "feast", desc: "Собор новомучеников и исповедников Соловецких празднуется 10 / 23 августа. Празднование установлено указом патриарха Московского и всея Руси Алексия II от 25 марта 2000 года." },
  { key: "08-23", name: "Второе обретение и перенесение мощей прп. Саввы, игумена Сторожевского, Звенигородского", kind: "saint", desc: "Прп. Савва Сторожевский, ученик прп. Сергия Радонежского, с юности посвятил себя монашеству. Став духовником братии и игуменом, он основал монастырь на Сторожевской горе, где наставлял иноков в молитве и трудах." },
  { key: "08-23", name: "Собор Валаамских святых", kind: "feast", desc: "4 июля 1999 года по благословению Патриарха Московского и всея Руси Алексия II был установлен день празднования памяти Собора Валаамских святых, который приходится на первое воскресенье после 6/19 августа." },
  { key: "08-23", name: "Сщмч. Афанасия Кислова, пресвитера", kind: "saint", desc: "Сщмч. Афанасий Кислов (1880-1937) родился в крестьянской семье и рано осиротел. Став священником в 1924 году, он стойко противостоял обновленческому расколу, несмотря на гонения." },
  { key: "08-24", name: "Попразднство Преображения Господня", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-24", name: "Сщмч. Евпла Катанского (Сицилийского), архидиакона", kind: "saint", desc: "Сщмч. Евпл, архидиакон, пострадал в 304 году в Катане (Сицилия) во время гонений Диоклетиана. Постоянно нося с собой Евангелие, он смело проповедовал Христа." },
  { key: "08-24", name: "прп. Феодора, инока, кн. Острожского, Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Феодор Острожский, потомок св. князя Владимира, прославился защитой православия на Волыни от католического влияния. После 1441 года, оставив княжеские владения и славу, принял монашество с именем Феодосий в Киево-Печерской лавре, где и скончался во второй половине XV века." },
  { key: "08-24", name: "прп. Иоанна Святогорского, затворника, иеросхимонаха", kind: "saint", desc: "Прп. Иоанн Святогорский (в миру Иван Крюков, 1795–1867) родился в Курске, в 38 лет поступил в Глинскую пустынь, где принял постриг. Позже перешел в Святогорскую обитель, где прославился как усердный эконом." },
  { key: "08-24", name: "обретение мощей прав. Иулиании Лазаревской, Муромской", kind: "saint", desc: "Праведная Иулиания Лазаревская (XVI в.) с юности вела благочестивую жизнь, помогая бедным и ухаживая за больными. Вышла замуж за Юрия Осорьина, родила шестерых детей." },
  { key: "08-25", name: "Попразднство Преображения Господня", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-25", name: "Сщмч. Александра, епископа Команского", kind: "saint", desc: "Сщмч. Александр Команский (III в.), ученый философ, добровольно принял подвиг юродства. Жил в бедности, занимаясь продажей угля. Когда в Комане потребовался новый епископ, свт." },
  { key: "08-25", name: "Василия Инфантьева", kind: "saint", desc: "Сщмч. Василий Инфантьев (1853-1918), священник Мехонской церкви Шадринского уезда, был убит 12/25 августа 1918 года в селе Таушкан во время антицерковных репрессий в Пермском крае." },
  { key: "08-25", name: "Алексия Лопатина", kind: "saint", desc: "Сщмч. Алексий Лопатин (1868-1918), выпускник Вятской духовной семинарии, 26 лет служил в селе Верховино, затем стал настоятелем Преображенского собора г." },
  { key: "08-25", name: "Леонида Бирюковича", kind: "saint", desc: "Сщмч. Леонид Бирюкович (1864-1937), выпускник Минской духовной семинарии, с 1899 года служил настоятелем Успенской церкви в селе Бродец. Неоднократно арестовывался: в 1934 году ‒ за хранение царских монет, в 1935 ‒ за организацию сопротивления закрытию храма (получил 6 лет лагерей, но был освобождён по болезни)." },
  { key: "08-25", name: "Иоанна Никольского", kind: "saint", desc: "Сщмч. Иоанн Никольский (1878-1937) служил священником в Тверской епархии. В 1929 году был арестован за опоздание с хлебосдачей и сослан. В 1933 году повторно арестован за посещение жены репрессированного священника, осуждён на 3 года ссылки в Казахстан." },
  { key: "08-25", name: "Николая Доброумова", kind: "saint", desc: "Сщмч. Николай Доброумов (1875/76-1937), сын священника, окончил Вологодскую духовную семинарию. С 1899 года служил в храмах Коми края, вел активную просветительскую деятельность." },
  { key: "08-26", name: "Отдание праздника Преображения Господня", kind: "feast", desc: "В православном календаре этот праздник называется « Преображение Господа Бога и Спаса нашего Иисуса Христа » и совершается сейчас 19 августа. Для многих любителей литературы он ассоциируется с замечательными стихами Бориса Пастернака." },
  { key: "08-26", name: "Преставление (662), перенесение мощей прп. Максима Исповедника", kind: "saint", desc: "Прп. Максим Исповедник (ок. 580-662) ‒ выдающийся богослов и защитник Православия. Родившись в Константинополе, он оставил высокий пост при императорском дворе, принял монашество и стал игуменом." },
  { key: "08-26", name: "обретение мощей блж. Максима Московского, Христа ради юродивого", kind: "saint", desc: "Блж. Максим, Христа ради юродивый, жил в Москве. Летом и зимой он ходил почти нагим, терпя зной и холод, говоря: «Хоть люта зима, но сладок рай». Его поучения слушали все ‒ от князей до бедняков." },
  { key: "08-26", name: "преставление (1783), второе обретение мощей (1991) свт. Тихона, епископа Воронежского, Задонского чудотворца", kind: "saint", desc: "Свт. Тихон (Тимофей Соколов) родился в 1724 году. С детства терпел нужду, чудом избежал солдатчины. Окончив Новгородскую семинарию, стал преподавателем, затем принял монашество.", lifeId: "tihon-zadonsky" },
  { key: "08-26", name: "Иоанна Шишева", kind: "saint", desc: "Сщмч. Иоанн Шишев (1867–1918) окончил Пермскую духовную семинарию. С 1887 года служил священником в селах Екатеринбургской епархии, активно занимался просветительской деятельностью: преподавал в церковноприходских школах, участвовал в миссионерской работе, организовывал духовные чтения." },
  { key: "08-26", name: "Иоасафа Панова", kind: "saint", desc: "Сщмч. Иоасаф Панов (1860–1918) окончил Далматовское духовное училище. С 1889 года служил диаконом, с 1891 года – священником в различных приходах Екатеринбургской епархии, включая села Нижнее и Мироновское." },
  { key: "08-26", name: "Константина Попова", kind: "saint", desc: "Сщмч. Константин Попов служил в селе Лягушинском Пермской губернии. 13/26 августа 1918 года был расстрелян большевиками в селе Егоршино. О священномученике Константине Ивановиче Попове известно мало." },
  { key: "08-26", name: "Серафима (Звездинского), епископа Дмитровского", kind: "saint", desc: "Сщмч. Серафим (Звездинский), в миру Николай, родился в 1883 году. Окончил Московскую духовную академию, принял монашество в 1908 году. В 1920 году хиротонисан во епископа Дмитровского, викария Московской епархии." },
  { key: "08-26", name: "Николая Орлова", kind: "saint", desc: "Сщмч. Николай Орлов (1881–1937) родился в Костромской губернии. Окончив Ярославскую духовную семинарию, в 1911 году принял священный сан и служил в родном селе Рыбницы." },
  { key: "08-26", name: "Иакова Архипова", kind: "saint", desc: "Сщмч. Иаков Архипов (1888–1937) родился в крестьянской семье Владимирской губернии. С юных лет пел на клиросе, после революции стал псаломщиком. В 1921 году принял священнический сан и служил в Преображенском соборе закрытого Спасо-Геннадиева монастыря." },
  { key: "08-26", name: "Алексия Введенского, диакона", kind: "saint", desc: "Сщмч. диакон Алексий Введенский (1903-1937) родился в семье священника Ярославской губернии. Окончив духовное училище, в 1925 году был рукоположен в диакона и служил в селе Петропавловское." },
  { key: "08-26", name: "мч. Василия Александрина", kind: "saint", desc: "Мч. Василий Александрин (1872-1942) родился в крестьянской семье в Пензенской губернии. До революции имел крепкое хозяйство, в 1918 году избран псаломщиком в храм родного села." },
  { key: "08-26", name: "Минская", year: "1500", kind: "saint", desc: "Минская икона Пресвятой Богородицы в конце X века была перенесена святым равноапостольным князем Владимиром из Корсуни в Киев и поставлена в Десятинной церкви (память освящения церкви в 996 году – 12 мая), в которой и пребывала более 500 лет." },
  { key: "08-26", name: "Семистрельная", year: "1830", kind: "saint", desc: "На Семистрельной иконе Пресвятая Богородица изображается без Богомладенца, склонившей Свою главу к правому плечу и пронзенной в грудь семью стрелами или мечами, из которых четыре находятся с левой стороны, а три с правой." },
  { key: "08-27", name: "Предпразднство Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "08-27", name: "Прор. Михея (из 12-ти пророков)", kind: "saint", desc: "Пророк Михей, один из 12 малых пророков, происходил из города Морасфы в Иудее. Пророчествовал около 50 лет (778-728 гг. до Р.Х.) при царях Иоафаме, Ахазе и Езекии, будучи современником пророка Исаии." },
  { key: "08-27", name: "Перенесение мощей прп. Феодосия, игумена Печерского", kind: "saint", desc: "Прпп. Антоний и Феодосий Печерские ‒ основатели русского монашества. Св. Антоний (ок. 983-1073), уроженец Любеча, принял постриг на Афоне, затем вернулся на Русь и поселился в пещере близ Киева (1051 г.).", lifeId: "pecherskie" },
  { key: "08-27", name: "Прп. Аркадия Новоторжского", kind: "saint", desc: "Прп. Аркадий Вяземский и Новоторжский (XI в.) подвизался в юродстве Христа ради. Родом из Вязьмы, он с детства отличался благочестием. Под духовным руководством прп." },
  { key: "08-27", name: "сщмч. Маркелла, епископа Апамейского", kind: "saint", desc: "Сщмч. Маркелл, епископ Апамейский, происходил из Кипра, оставил высокие должности ради монашества. Избранный епископом Апамеи, ревностно боролся с язычеством." },
  { key: "08-27", name: "Сщмч. Василия (Богоявленского), архиепископа Черниговского,", kind: "saint", desc: "Сщмч. Василий (Богоявленский), архиепископ Черниговский (1867-1918), родился в Тамбовской губернии. Окончив Казанскую духовную академию, принял монашество после смерти супруги (1908)." },
  { key: "08-27", name: "прмч. Матфея (Померанцева), архимандрита", kind: "saint", desc: "Прмч. Матфей (Померанцев, ок. 1881-1918) ‒ выпускник Киевской духовной академии, преподаватель духовных школ, с 1917 года ‒ ректор Пермской духовной семинарии." },
  { key: "08-27", name: "мч. Алексия Зверева", kind: "saint", desc: "Мч. Алексий Зверев (1867/68-1918) ‒ крестьянин, миссионер Московской епархии, делегат Поместного Собора 1917-1918 гг. В августе 1918 года вошёл в состав комиссии, расследовавшей убийство архиеп." },
  { key: "08-27", name: "сщмч. Владимира Цедринского, пресвитера", kind: "saint", desc: "Сщмч. Владимир Цедринский (†1918) ‒ священник Туркестанской епархии, служивший в Лепсинске (Семиречье). Активно защищал права Церкви, за что подвергся гонениям." },
  { key: "08-27", name: "Владимира Смирнова", kind: "saint", desc: "Сщмч. Владимир Смирнов (1885-1937) ‒ московский священник, выпускник духовной семинарии и юридического факультета. Служил консультантом у патриарха Тихона." },
  { key: "08-27", name: "Николая Толгского", kind: "saint", desc: "Сщмч. Николай Толгский (1886-1937) ‒ выпускник Московской духовной академии. Служил в московских храмах, был благочинным Сретенского округа. Трижды арестовывался: в 1922 г." },
  { key: "08-27", name: "прмч. Елевферия (Печенникова), схиархимандрита", kind: "saint", desc: "Прмч. Елевферий (Печенников, 1870-1937) ‒ уроженец Могилёвской губернии, бывший полковой священник, монах Смоленского Троицкого монастыря. Неоднократно арестовывался (1922, 1924, 1930 гг.)." },
  { key: "08-27", name: "Евы (Павловой), игумении", kind: "saint", desc: "Прмц. Ева (Павлова, 1879-1937) ‒ игумения пензенского монастыря. Впервые арестована в 1929 году (3 или 8 лет ссылки в Казахстан). Вторично арестована в 1937 году по делу \"тайного монастыря\" в Чимкенте, обвинена в контрреволюционной деятельности." },
  { key: "08-27", name: "Евдокии (Перевозниковой), монахини", kind: "saint", desc: "Прмц. Евдокия (Перевозникова, 1880-1937) родилась в Вологодской губернии, до революции подвизалась в монастыре. Последовала за ссыльным митрополитом сщмч." },
  { key: "08-28", name: "Успение Пресвятой Владычицы нашей Богородицы и Приснодевы Марии", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "08-28", name: "София – Премудрость Божия", year: "Новгородская", kind: "saint", desc: "Чудотворная икона Божией Матери «София – Премудрость Божия» имеется во многих храмах России и сводится к двум типам: Киевскому и Новгородскому. Первая икона «Софии – Премудрости Божией» появилась в Новгороде в XV в., хотя первая церковь на " },
  { key: "08-28", name: "Успение Киево-Печерская", year: "1073", kind: "saint", desc: "Киево-Печерская икона Успения Пресвятой Богородицы - одна из древнейших явленных икон в Русской Православной Церкви. Пресвятая Богородица вручила ее 4-м византийским зодчим , которые в 1073 году принесли икону преподобным Антонию и Феодосию Печерским." },
  { key: "08-28", name: "Успение Овиновская", year: "1425", kind: "saint", desc: "История появления иконы «Успения» Божией Матери Овиновской связана с Паисиевским мужским монастырем (быв. Костромская губерния). Во время княжения на Руси Димитрия Донского, некий боярин по имени Иван Овинов, живший около г." },
  { key: "08-28", name: "Успение Псково-Печерская", year: "1472", kind: "saint", desc: "В небольшом городе Печеры, к западу от Пскова, расположен монастырь, также называемый Печерским. Как город, так и монастырь получили свое название от вырубленной неизвестно когда и кем в горе древней пещеры." },
  { key: "08-28", name: "Успение (Семигородная)", year: "XV", kind: "saint", desc: "«Семигородная», или «Семигородская», икона «Успение Пресвятой Богородицы» написана преподобным Дионисием Глушицким (память 14 июня по новому стилю), основателем Глушицкой обители, находящейся в Кадниковском уезде Вологодской губернии, к северу от Вологды, на речке Глушице." },
  { key: "08-28", name: "Успение Пюхтицкая", year: "XVI", kind: "saint", desc: "В Эстляндской губернии, в 16 верстах на северо-запад от Чудского озера и в 25 верстах от Балтийской железной дороги, там, где эта губерния соприкасается с Псковской и Санкт-Петербургской, находится живописной местности высокая гора, подымающаяся тремя уступами." },
  { key: "08-28", name: "Моздокская (Иверская)", year: "XIII", kind: "saint", desc: "Грузинская царица святая Тамара, жившая в конце XII – начале XIII века, способствовала распространению на Кавказе христианства, воздвигала и снабжала утварью и облачениями множество храмов в горах и ущельях." },
  { key: "08-28", name: "Ацкурская", kind: "saint", desc: "Предание говорит о том, что чудотворный Ацкурский образ – копия нерукотворной иконы Божией Матери, принесенный в Грузию святым апостолом Андреем Первозванным." },
  { key: "08-28", name: "Цилканская", year: "IV", kind: "saint", desc: "Цилканская икона Божией Матери по своему происхождению современна святой равноапостольной Нине, просветительнице Грузии, жившей в IV веке. В настоящее время святой образ находится в Цилканском храме в Карталинии." },
  { key: "08-28", name: "Влахернская", year: "Грузинская", kind: "saint", desc: "Влахернская (Грузинская, Квабтахевская) икона Божией Матери находится в Квабтахевском монастыре, который расположен юго-западнее Мцхета, на правой стороне реки Куры (Грузия)." },
  { key: "08-28", name: "Владимирская (Ростовская)", year: "XII", kind: "saint", desc: "О происхождении чудотворной Владимирской иконы Божией Матери, которая находилась в кафедральном Успенском соборе Ростова Великого, в житии преподобного Алипия Печерского рассказывается следующее." },
  { key: "08-28", name: "Гаенатская", year: "XIII", kind: "saint", desc: "Название этой иконы Божией Матери связано с Гелатским (Гаенатским) монастырём, расположенным близ города Кутаиси. Монастырь основал в 1106 году грузинский царь Давид IV Строитель." },
  { key: "08-28", name: "Бахчисарайская", year: "Крымская, Мариупольская", kind: "saint", desc: "Бахчисарайская икона Божией Матери, согласно преданию, явилась в Крыму близ г. Бахчисарая. Кроме упомянутого имени, икона носила еще и другие названия, в частности: Панагия, Крымская икона Богоматери и Мариупольская." },
  { key: "08-29", name: "Попразднство Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "08-29", name: "Перенесение из Едессы в Константинополь Нерукотворенного Образа (Убруса) Господа Иисуса Христа", year: "944", kind: "feast", desc: "Перенесение из Едессы в Константинополь Нерукотворного Образа Господа нашего Иисуса Христа было в 944 г. Предание свидетельствует, что во времена проповеди Спасителя в сирийском городе Едессе правил Авгарь ." },
  { key: "08-29", name: "Мч. Диомида врача", kind: "saint", desc: "Мч. Диомид (III в.) ‒ врач из Тарса, обращавший язычников в христианство. Прославился даром духовного и телесного врачевания. Во время гонений Диоклитиана был арестован в Никее." },
  { key: "08-29", name: "Мчч. 33-х Палестинских", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "08-29", name: "Прп. Херимона Египетского", kind: "saint", desc: "Прп. Херимон (IV-V вв.) подвизался в Египте, в Скитской пустыне. Достигнув столетнего возраста, скончался за рукоделием. Упоминается в \"Лавсаике\" Палладия, алфавитном Патерике и в Триоди Постной." },
  { key: "08-29", name: "мч. вел. кн. Константина Брынковяну (1714)", kind: "saint", desc: "Мч. Константин Брынковяну (1654-1714) ‒ правитель Валахии, заботившийся о духовном просвещении народа. За верность православию и связи с Россией был вызван в Стамбул, где вместе с четырьмя сыновьями и советником принял мученическую смерть, отказавшись принять ислам." },
  { key: "08-29", name: "Сщмч. Александра Соколова, пресвитера", kind: "saint", desc: "Сщмч. Александр Соколов (1893-1937) ‒ священник из Новгородской губернии, выпускник духовной семинарии. Служил в сельских храмах Череповецкого уезда и Тверской области." },
  { key: "08-29", name: "прмц. Анны (Ежовой), монахини", kind: "saint", desc: "Прмц. Анна (Ежова, 1885-1937) ‒ монахиня из Нижегородской губернии. Проживала в посёлке Гнилицы под Нижним Новгородом. Арестована летом 1937 года по обвинению в участии в \"церковной контрреволюционной группе\"." },
  { key: "08-29", name: "мч. Иакова Гортинского", kind: "saint", desc: "Мч. Иаков Гортинский (1899-1937) ‒ механик горьковской больницы, арестованный в 1937 году по обвинению в \"церковной контрреволюционной деятельности\". Не признав вины, был расстрелян 29 августа 1937 года вместе с группой верующих, включая прмц." },
  { key: "08-29", name: "Феодоровская", kind: "saint", desc: "Судьба этого чудотворного образа тесно переплетена с судьбами России, ибо Феодоровская была родовой иконой дома Романовых. Сама икона, по преданию написанная апостолом и евангелистом Лукою , была обретена святым благоверным князем Георгием Всеволодовичем в часовне близ волжского Городца." },
  { key: "08-29", name: "Торжество Пресвятой Богородицы (Порт-Артурская)", year: "1904", kind: "saint", desc: "11 декабря 1903 года, за два месяца до начала русско-японской войны, в Дальние пещеры Киево-Печерской лавры пришел старик-матрос, участник обороны Севастополя." },
  { key: "08-30", name: "Попразднство Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "08-30", name: "Сщмч. Мирона Кизического, пресвитера", kind: "saint", desc: "Мч. Мирон (III в.) ‒ пресвитер из Ахаии (Греция), пострадавший при императоре Декии. Во время рождественского богослужения в 250 году смело заступился за паству перед правителем Антипатром." },
  { key: "08-30", name: "прп. Пимена Угрешского, архимандрита", kind: "saint", desc: "Прп. Пимен (Мясников, 1810-1880) ‒ уроженец Вологды, с юности стремился к монашеству. В 1832 году поступил в Новоезерский монастырь, затем перешел в Оптину Пустынь." },
  { key: "08-30", name: "Прп. Алипия, иконописца Печерского, в Ближних пещерах", kind: "icon", desc: "Прп. Алипий Печерский (†1114) ‒ один из первых русских иконописцев, ученик греческих мастеров, расписывавших Киево-Печерскую лавру. Прославился чудотворениями: краски в его руках исцелили прокажённого, ангелы помогали ему в написании икон." },
  { key: "08-30", name: "Левкия", kind: "saint", desc: "Мчч. Фирс, Левкий и Каллиник пострадали в Кесарии Вифинской при императоре Декии (III в.). Левкий был усечен мечом. Фирс чудесным образом перенёс пытки и мирно скончался." },
  { key: "08-30", name: "Короната (Корнута) и дружины их", kind: "saint", desc: "Мученики Фирс, Левкий, Коронат и дружина их пострадали в Кесарии Вифинской и Аполлонии при императоре Декии (249–251). (Возможно, что Коронат есть одно лицо с Корнутом, память которого отмечается 12 сентября)." },
  { key: "08-30", name: "мч. Патрокла Трикассинского (Труасского)", kind: "saint", desc: "Мч. Патрокл († ок. 275) был родом из Трикассины (ныне Труа, Франция). При императоре Аврелиане отказался поклониться идолам, обличив правителя. Приговорённый к казни, чудесно перешёл реку Сену по воде, но был настигнут воинами и умерщвлён." },
  { key: "08-30", name: "Собор Кузбасских святых", kind: "feast", desc: "16 февраля 2011 года в ответ на обращение епископа Кемеровского и Новокузнецкого Аристарха с благословения патриарха Московского и всея Руси Кирилла в православный месяцеслов было внесено празднование Собора Кемеровских (Кузбасских) святых." },
  { key: "08-30", name: "Сщмч. Николая Околовича, пресвитера", kind: "saint", desc: "Сщмч. Николай Околович (1863-1934) родился в семье псаломщика Витебского уезда. Окончил Витебскую духовную семинарию и Московскую духовную академию. Служил законоучителем, возглавлял церковные общества." },
  { key: "08-30", name: "сщмч. Димитрия Остроумова, пресвитера", kind: "saint", desc: "Сщмч. Димитрий Остроумов (1869-1937) родился в Московской губернии. Окончив Московскую духовную семинарию, служил учителем, а в 1906 году был рукоположен во священника." },
  { key: "08-30", name: "Свенская (Печерская)", year: "1288", kind: "saint", desc: "Свенская Печерская икона Божией Матери имеет 2 празднования: 3 мая, в день кончины преподобного Феодосия Печерского (см. о ней под этим числом), и 17 августа, в день кончины преподобного Алипия Печерского , который ее написал." },
  { key: "08-30", name: "Прибавление ума", year: "Подательница ума", kind: "saint", desc: "Данные исследователей говорят о том, что иконография образа сложилась в XVI веке под влиянием западных гравюр и икон со сложной символикой. Однако большая часть сохранившихся икон «Прибавление ума» относится к XVIII-XIX векам." },
  { key: "08-31", name: "Попразднство Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "08-31", name: "Иоанна V", kind: "saint", desc: "Свт. Иоанн V был патриархом Константинопольским с 669 по 674 год при императоре Константине Погонате. Святитель Иоанн V был патриархом Константинопольским с 669 года по 674 год, а святитель Георгий I – с 678 года по 683 год, оба при императ" },
  { key: "08-31", name: "Георгия I (683), патриархов Константинопольских", kind: "saint", desc: "Свт. Георгий (†686) возглавил Константинопольскую кафедру в 679 году. Главным событием его патриаршества стал VI Вселенский Собор (680-681), созванный для преодоления раскола с Римом из-за монофелитства.", lifeId: "georgiy" },
  { key: "08-31", name: "прп. Макария, игумена Пеликитского", kind: "saint", desc: "Прп. Макарий, игумен Пеликитский, родился в Константинополе. Принял монашество в Пеликитской обители под руководством прп. Илариона. После смерти наставника братия избрала Макария игуменом." },
  { key: "08-31", name: "прп. Иоанна Рыльского", kind: "saint", desc: "Прп. Иоанн Рыльский, великий болгарский святой, родился около 876 года в селе Скрино. Рано осиротев, стал пастухом, после раздал имущество и ушел в пустыню." },
  { key: "08-31", name: "Сщмч. Григория Бронникова, пресвитера", kind: "saint", desc: "Сщмч. Григорий Бронников родился в 1876 году в семье диакона в Коми крае. С 1921 года служил священником в селе Селиб. В 1930 году был объявлен \"кулаком\", а в 1937-м арестован за \"контрреволюционную агитацию\" после закрытия храма." },
  { key: "08-31", name: "Евгения Дмитрева", kind: "saint", desc: "Мч. Евгений Дмитрев родился в семье священника, служил псаломщиком в селе Митино Рязанской области, затем работал на заводе в Перми. В 1937 году был арестован вместе со всеми работниками завода и, как предполагается, расстрелян 31 августа." },
  { key: "08-31", name: "Михаила Ерегодского, чтецов", kind: "saint", desc: "Мч. Михаил Ерегодский (1878-1937), потомственный церковнослужитель, был псаломщиком. В 1930-е годы его семья подверглась гонениям: конфисковали имущество, дом, арестовали старших детей." },
  { key: "08-31", name: "Всецарица", year: "Пантанасса", kind: "saint", desc: "Чудотворная икона Божией Матери, именуемая «Всецарица» (по-гречески – «Пантанасса») находится на Святой Горе Афон в Греции в соборном храме Ватопедской обители , слева от царских врат." },
];
